const body = $input.first().json.body;
if (!body || !body.email || !body.full_name || !body.activation_link) {
  throw new Error('Missing required fields: email, full_name, and activation_link are required');
}
return {
  json: {
    email: body.email,
    full_name: body.full_name || 'New User',
    company_name: body.company_name || 'Our Platform',
    activation_link: body.activation_link
  }
};

const error = $input.first().json;
return {
  json: {
    status: "error",
    email: $json.email,
    error_message: error?.message || error?.error || 'Unknown error',
    timestamp: new Date().toISOString()
  }
};
